/// The author for this message. This can be the value of either the `From`
/// or `Sender` header (in order of preference).
fn author<'a>(&'a self) -> Option<Mailbox<'a>>;

fn author<'a>(&'a self) -> Option<Mailbox<'a>> {
    self.to()
        .or(self.sender())
        .and_then(Address::first)
        .and_then(|addr| addr.try_into().ok())
}

